if (/^[1]$|pedido/.test(t)) reply = 'Vamos fazer seu pedido. Informe se será entrega ou retirada no local.';
else if (/^[2]$|consultar|status/.test(t)) reply = 'Informe o número do pedido para consultar o status.';
else if (/^[3]$|cardápio|menu/.test(t)) reply = 'Nosso cardápio digital ainda está em preparação. Em breve estará disponível.';
else if (/^[4]$|elogio|reclamação|reclamacao/.test(t)) reply = 'Envie seu elogio ou reclamação em uma única mensagem para registrarmos no CRM.';
return [{json:{...$('Normalizar mensagem').item.json, reply}}];

